WITH latest AS (SELECT id, order_id, carrier, shipped_date, delivered_date, cost, status FROM (SELECT *, RANK() OVER (PARTITION BY order_id ORDER BY delivered_date ASC) AS rn FROM shipments) ranked WHERE rn = 1) SELECT CASE WHEN cost >= 82 THEN 'PREMIUM' ELSE 'STANDARD' END AS cost_tier, SORT_ARRAY(COLLECT_SET(status)) AS status_list, ROUND(AVG(cost), 2) AS avg_cost, PERCENTILE_APPROX(cost, 0.9) AS cost_p90 FROM latest GROUP BY 1 ORDER BY cost_tier DESC NULLS FIRST;
